"""Render a concise, evidence-linked report for the S2 memory-function study."""
import json
from html import escape as e
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs
from build_answering_results import CSS,table,link

ROOT=Path(__file__).resolve().parents[1]


def main():
    d=json.loads((ROOT/'research/note-functions/progress.json').read_text())
    add_signature='add_note(topic, fact, owner, status, source_ids)' if d.get('api_revision')=='v2' else 'add_note(fields, source_ids)'
    update_signature='update_note(note_id, source_ids, optional changed fields)' if d.get('api_revision')=='v2' else 'update_note(note_id, changes, source_ids)'
    body='<header class="hero"><p class="small">S2 study · '+e(d['updated'])+'</p><h1>Editing meeting notes with function calls</h1></header>'
    body+='<section id="findings"><h2>Current findings and progress</h2><ul>'+''.join('<li>'+e(x['text'])+' '+link(x['url'],'Details')+'</li>' for x in d['brief'])+'</ul><p>'+link('../todo.html','Project checklist')+' · '+link('../daily-log.html','Daily log')+' · '+link('full-answering-results.html#scores','Earlier 105-question scores')+'</p></section>'
    body+='<section id="progress"><h2>1. Execution and validation</h2><p>The current authorization covers this S2 study; DuplexOmni remains stopped. A completed run is reviewed separately for answer correctness and note accuracy.</p>'+table(1,'Current study stages; statuses describe saved evidence.',['Stage','Status','Evidence'],[[e(x['stage']),e(x['status']),e(x['evidence'])] for x in d['stages']])
    if d['jobs']:
        body+=table(2,'Study jobs; text weights and an 8 GiB KV cache share GPU 0; stages run sequentially.',['Work','Scheduler state','Completed outputs','Requested GPUs'],[[e(x['label']),e(x['state']),e(x['completed']),str(x['GPUs'])+' · '+e(x['GPU_type'])] for x in d['jobs']])
    body+='</section><section id="design"><h2>2. What each model receives and produces</h2><p>At each existing 25–40 second transcript boundary, the Instruct note writer receives the new speaker-attributed speech, ten seconds of preceding context, one current note state and short receipts from the preceding edits. It sees neither the future question nor its reference answer. Both edit conditions decode freely with the same function descriptions, fields, operations and output cap.</p><p>The writer produces JSON operations or native Qwen function calls. The program validates each operation, executes accepted edits and assigns stable note IDs. The next update receives the changed state and receipts; previous snapshots are not accumulated. The current view is limited to 4,096 tokens and contains notes, eight recent changes and original transcript evidence. The full version history is retained on disk.</p>'+table(3,'Matched answer conditions; every final thinker retains the full available transcript and receives the same focused answer prompt.',['Condition','Saved material','Purpose'],[['Reactive','None.','Baseline without earlier note generation.'],['Current source notes','Selected original utterances and revision links.','Reference method from the completed study.'],['Editable notes · JSON','One current note state, changed through JSON operations.','Measure explicit editing with compact factual notes.'],['Editable notes · native calls','The same note format and operations, using the checkpoint’s native function-call template.','Measure the effect of the function-call interface.']])
    body+='<p>The common writer is Qwen3-30B-A3B-Instruct-2507. Final thinkers are the pinned Instruct and Thinking variants of Qwen3-30B-A3B-2507. Thinking reports native request-time reasoning tokens; Instruct has no separate thinking channel. Earlier note outputs are counted separately from request-time thinking.</p></section>'
    body+='<section id="functions"><h2>3. Memory operations and changes</h2>'+table(4,'Functions executed by the same memory store in both edit conditions.',['Function','Effect'],[[add_signature,'Create a distinct fact, commitment or unresolved issue; return its note ID.'],[update_signature,'Change the same task/aspect using new speech; retain the earlier version and its evidence.'],['delete_note(note_id, reason)','Remove a duplicate or mistaken note from the current view; retain the deletion record.'],['link_notes(first_id, second_id, relation)','Connect existing notes through a revision, confirmation, explanation, qualification or reference.'],['no_change()','Leave the notes unchanged.']])+'<p>Each note contains a topic, short factual text, owner, decision status and source IDs. Source IDs identify transcript passages; note IDs identify program-maintained notes. Add and update operations require at least one newly arrived source. The program rejects edits that break the function schema, cite unavailable speech, exceed size limits or lack that new evidence. Source words, speaker labels and timestamps are copied by the program. These mechanical checks do not establish that a generated fact or owner is correct.</p><p><strong>Illustration:</strong> Friday is first proposed for sending the slides; Monday is later agreed. The current note changes to Monday, while the change record retains Friday and both supporting passages. A cancellation changes the plan’s status. Automatic budget eviction is recorded separately from model-requested deletion.</p><p>'+link('../research/note-functions/functions.json','Exact function schemas and writer instructions')+'</p></section>'
    if d.get('repair_attempts'):
        body+='<section id="update-feedback"><h3>Flat arguments and one correction turn</h3><p>The revised interface puts source IDs beside the other function arguments. If an output has invalid syntax or arguments, the program returns the error immediately and allows one correction generation for that segment. Accepted edits remain applied. Both generations and their complete inputs count toward the earlier token cost. Confirming a deadline should preserve the task owner; quantities and participant-specific access reports remain separate.</p><details id="initial-pilot"><summary>Why the first pilot was revised</summary><p>The original interface produced three malformed outputs and 28 rejected operations across 134 updates. In authored controls it changed an owner when another speaker merely confirmed a deadline, confused posts with people, and skipped file-access changes. These errors blocked full evaluation. The revised pilot adds five controls with different speakers or values.</p><p>'+link('../research/note-functions/initial-pilot-analysis.json','First pilot scores and actual answers')+'</p></details></section>'
    analysis=d.get('analysis')
    if analysis:
        def metric(row,key,percent=False):
            value=row['metrics'][key]['mean']
            if value is None:return 'Not exposed' if key=='native_thinking_tokens' else '—'
            return f'{100*value:.1f}%' if percent else f'{value:,.1f}'
        names={'reactive':'Reactive','source':'Source notes','json':'JSON edits','tools':'Native calls'}
        body+='<section id="results"><h2>Preliminary '+e(analysis['scope'])+' results</h2><p>These automatic scores use the unchanged qualified evaluator and ten repeated evaluator controls; source content review remains pending. Development contains six previously inspected questions and uses A100 hardware; the primary full-study latency comparison uses isolated H100 requests. Missing judge outputs are reported separately: '+str(analysis['unresolved_judgments'])+'.</p>'
        body+=table(5,'Answer accuracy and request-time work; Thinking seeds are averaged per question before computing means.',['Thinker','Condition','Required facts','Fully supported','Thinking tokens','First-answer seconds'],[[e(r['model']),names[r['condition']],metric(r,'core_correct',True),metric(r,'supported_correct',True),metric(r,'native_thinking_tokens'),metric(r,'first_answer_seconds')]for r in analysis['method_summary']])
        for number,name,caption in [(1,'answer-accuracy','Answer accuracy with 95% intervals from resampling meetings.'),(2,'paired-request-work','Thinking-model differences from reactive; negative values mean less request-time work. Intervals crossing zero do not establish an improvement.')]:
            body+='<figure id="fig-'+name+'"><img src="../research/note-functions/'+name+'.svg" alt="'+e(caption,quote=True)+'" style="width:100%;height:auto"><figcaption><strong>Figure '+str(number)+'.</strong> '+e(caption)+' '+link('../research/note-functions/'+name+'.pdf','PDF')+'</figcaption></figure>'
        def count(v):return 'Not allocated' if v is None else f'{v:,}'
        body+=table(6,'Generated tokens: one writer pass plus one set of requests at seed 23; shared writer work is counted once per hypothetical system.',['Thinker','Condition','Earlier generation','Request generation','Combined generation'],[[e(r['model']),names[r['condition']],count(r['earlier_generated_tokens']),count(r['request_generated_tokens']),count(r['total_generated_tokens'])]for r in analysis['total_cost']])
        body+='<p>The development source-note baseline reuses the prior full-study writer; its generation cost is not allocated to this small subset. Full evaluation reports the complete source-note cost over 26 meetings. Function definitions, receipts and transcript tokens enter logical input counts; generated-token totals do not equal total GPU compute.</p>'
        if analysis['scope']=='full':body+='<figure id="fig-total-generated-cost"><img src="../research/note-functions/total-generated-cost.svg" alt="Earlier note generation and request-time generation across four conditions" style="width:100%;height:auto"><figcaption><strong>Figure 3.</strong> Earlier generation, request-time thinking, answer formatting and channel delimiters for one writer pass over 26 meetings plus 105 Thinking requests, seed 23. '+link('../research/note-functions/total-generated-cost.pdf','PDF')+'</figcaption></figure>'
        body+='<p>'+link('../research/note-functions/analysis.json','Scores, intervals, token counts and final answers')+'</p></section>'
    body+='<section id="examples"><h2>4. Actual model examples</h2>'
    if analysis:
        grouped={}
        for row in analysis['answers']:grouped.setdefault(row['question_id'],[]).append(row)
        for question_id,rows in grouped.items():
            body+='<details><summary>'+e(rows[0]['question'])+'</summary><p><strong>Reference answer:</strong> '+e(rows[0]['reference_answer'])+'</p><ul>'
            for row in rows:body+='<li><strong>'+e(row['model']+' · '+names[row['condition']]+' · seed '+str(row['seed']))+':</strong> '+e(row['answer'] or '[Empty answer]')+' <span class="small">Fully supported: '+('unresolved' if row['supported_correct'] is None else 'yes' if row['supported_correct'] else 'no')+'.</span></li>'
            body+='</ul></details>'
    if not d['examples']:body+='<p>Model examples will appear after inference produces saved outputs.</p>'
    for ix,x in enumerate(d['examples'],1):
        body+='<details><summary>'+e(x['title'])+'</summary><p>'+e(x.get('description',''))+'</p><pre class="native">'+e(json.dumps(x['content'],ensure_ascii=False,indent=2))+'</pre></details>'
    body+='</section><section id="evaluation"><h2>5. Evaluation and interpretation</h2><p>The development set contains six previously inspected questions from five meetings, plus '+str(d.get('control_count',5))+' authored checks for revised deadlines, distinct tasks, speaker ownership, file visibility and quantities with different meanings. Control cases are excluded from the 105-question scores and meeting token totals. Full evaluation requires development output review and a frozen design.</p><p>All 105 existing questions across 26 meetings are retained for the later comparison. Results will separately identify the 18 questions used in earlier note tuning and the 44 questions from other meetings; the full bank is not an unseen test set. Reference answers and scorer prompts are unchanged.</p><ul><li>Report required-fact accuracy and fully supported accuracy, with invalid judge outputs shown separately.</li><li>Measure native request-time thinking tokens and actual first-answer/completion time; cold timing uses serial requests on one isolated H100.</li><li>Count all earlier input/output tokens, function definitions, receipts, rejected edits and unused updates, together with request-time costs.</li><li>Inspect duplicate facts, missed evidence, incorrect owners, changed decisions and notes dropped by the memory budget.</li></ul><p>Useful edits must preserve answer quality and improve request-time work or cost. Function-call syntax alone does not establish a latency benefit. Notes plus transcript lookup is a later, separately gated comparison.</p></section>'
    body+='<section id="next"><h2>Next steps and goals</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in d['next_steps'])+'</ul><p>Development uses one A100 SXM4 80 GB after the H100 start estimate moved overnight; superseded H100 requests were cancelled before allocation. The main controlled latency study remains on H100 SXM 80 GB. Each GPU job places weights and KV cache on GPU 0; stages run sequentially, with at most one study GPU active. CPU continuation and reporting use 0 GPUs. vLLM uses BF16, CUDA graphs and prefix caching; controlled timing resets the prefix cache before each request.</p></section>'
    page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="S2 memory-function experiments: meeting-note edits, answer accuracy, request-time thinking and total token cost."><title>Note-editing functions · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+CSS+'pre.native{white-space:pre-wrap;overflow-wrap:anywhere;max-height:36rem;overflow:auto}details{margin:1rem 0}summary{cursor:pointer}</style></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs('note-functions')+'</div><main id="main" class="container results">'+body+'</main></body></html>\n'
    (ROOT/'experiments/note-functions.html').write_text(page)


if __name__=='__main__':main()
